section.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/incident-comms-bundle.json",
  "title": "IncidentCommsBundle",
  "type": "object",
  "required": ["service", "header", "severity_matrix", "token_list", "templates", "incidents"],
  "additionalProperties": false,
  "definitions": {
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
    "datetime_tz": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}(:[0-9]{2})?(Z|[+-][0-9]{2}:[0-9]{2})$"},
    "person": {"type": "string", "minLength": 2, "not": {"pattern": "(?i)^(team|on-call|tbd|everyone|n/a)$"}},
    "audience": {"enum": ["status_page", "customer_email", "exec_brief", "internal_channel"]},
    "severity": {"type": "string", "pattern": "^(P[1-4]|SEV[1-4])$"},
    "filled_text": {"type": "string", "minLength": 20, "not": {"pattern": "\\{\\{[a-z_]+\\}\\}|<!--"}},
    "template": {
      "type": "object",
      "required": ["body", "last_drilled"],
      "properties": {
        "body": {"type": "string", "minLength": 40},
        "last_drilled": {"$ref": "#/definitions/date"}
      }
    },
    "external_review": {
      "type": "object",
      "required": ["unconfirmed_cause", "blame", "internal_names", "customer_pii"],
      "properties": {
        "unconfirmed_cause": {"const": false},
        "blame": {"const": false},
        "internal_names": {"const": false},
        "customer_pii": {"const": false}
      }
    }
  },
  "properties": {
    "__faion_header__": {"type": "object"},
    "service": {"type": "string", "minLength": 2},
    "header": {
      "type": "object",
      "required": ["owner", "version", "last_reviewed"],
      "properties": {
        "owner": {"type": "string", "pattern": "^[a-z][a-z0-9-]*:[a-z0-9._-]+$"},
        "version": {"type": "string", "pattern": "^[0-9]+\\.[0-9]+\\.[0-9]+$"},
        "last_reviewed": {"$ref": "#/definitions/date"}
      }
    },
    "severity_matrix": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["severity", "audiences", "first_post_deadline_minutes", "update_interval_minutes", "post_incident_email_deadline_hours"],
        "properties": {
          "severity": {"$ref": "#/definitions/severity"},
          "audiences": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"$ref": "#/definitions/audience"}},
          "first_post_deadline_minutes": {"type": "integer", "minimum": 1, "maximum": 240},
          "update_interval_minutes": {"type": "integer", "minimum": 5, "maximum": 240},
          "post_incident_email_deadline_hours": {"type": "integer", "minimum": 1, "maximum": 240}
        }
      }
    },
    "token_list": {"type": "array", "minItems": 4, "uniqueItems": true, "items": {"type": "string", "pattern": "^[a-z][a-z_]*$"}},
    "templates": {
      "type": "object",
      "required": ["status_page", "customer_email", "exec_brief", "internal_channel"],
      "additionalProperties": false,
      "properties": {
        "status_page": {"allOf": [{"$ref": "#/definitions/template"}, {"properties": {"body": {"allOf": [{"pattern": "\\{\\{state\\}\\}"}, {"pattern": "\\{\\{timestamp\\}\\}"}, {"pattern": "\\{\\{impact\\}\\}"}, {"pattern": "\\{\\{next_update_at\\}\\}"}]}}}]},
        "customer_email": {"allOf": [{"$ref": "#/definitions/template"}, {"properties": {"body": {"allOf": [{"pattern": "\\{\\{impact\\}\\}"}, {"pattern": "\\{\\{next_update_at\\}\\}"}]}}}]},
        "exec_brief": {"allOf": [{"$ref": "#/definitions/template"}, {"properties": {"body": {"allOf": [{"pattern": "\\{\\{customer_impact\\}\\}"}, {"pattern": "\\{\\{eta\\}\\}"}, {"pattern": "\\{\\{decisions_needed\\}\\}"}, {"pattern": "\\{\\{what_is_being_done\\}\\}"}, {"pattern": "\\{\\{next_update_at\\}\\}"}]}}}]},
        "internal_channel": {"allOf": [{"$ref": "#/definitions/template"}, {"properties": {"body": {"allOf": [{"pattern": "\\{\\{severity\\}\\}"}, {"pattern": "\\{\\{commander\\}\\}"}, {"pattern": "\\{\\{comms_lead\\}\\}"}, {"pattern": "\\{\\{blast_radius\\}\\}"}, {"pattern": "\\{\\{hypothesis\\}\\}"}, {"pattern": "\\{\\{actions\\}\\}"}, {"pattern": "\\{\\{incident_link\\}\\}"}, {"pattern": "\\{\\{next_checkpoint_at\\}\\}"}]}}}]}
      }
    },
    "incidents": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["incident_id", "severity", "declared_at", "audiences_sent", "updates", "internal_post"],
        "additionalProperties": false,
        "properties": {
          "incident_id": {"type": "string", "pattern": "^INC-[0-9]+$"},
          "severity": {"$ref": "#/definitions/severity"},
          "declared_at": {"$ref": "#/definitions/datetime_tz"},
          "audiences_sent": {"type": "array", "uniqueItems": true, "items": {"$ref": "#/definitions/audience"}},
          "updates": {
            "type": "array",
            "minItems": 1,
            "items": {
              "type": "object",
              "required": ["channel", "posted_at", "minutes_after_declaration", "text", "next_update_at", "approved_by"],
              "properties": {
                "channel": {"enum": ["status_page", "customer_email"]},
                "state": {"enum": ["Investigating", "Identified", "Monitoring", "Resolved"]},
                "posted_at": {"$ref": "#/definitions/datetime_tz"},
                "minutes_after_declaration": {"type": "integer", "minimum": 0},
                "text": {"$ref": "#/definitions/filled_text"},
                "impact": {"type": "string", "minLength": 10},
                "component_status_matches_text": {"type": "boolean"},
                "next_update_at": {"anyOf": [{"$ref": "#/definitions/datetime_tz"}, {"type": "null"}]},
                "review": {"$ref": "#/definitions/external_review"},
                "approved_by": {"$ref": "#/definitions/person"}
              },
              "allOf": [
                {"if": {"properties": {"channel": {"const": "status_page"}}}, "then": {"required": ["state", "impact", "component_status_matches_text"], "properties": {"component_status_matches_text": {"const": true}}}},
                {"if": {"properties": {"state": {"const": "Resolved"}}, "required": ["state"]}, "else": {"required": ["review"], "properties": {"next_update_at": {"type": "string"}, "text": {"allOf": [{"pattern": "(?i)next update (by|at) "}, {"not": {"pattern": "(?i)(we believe|likely caused|appears to be|root cause (is|was)|caused by)"}}]}}}}
              ]
            }
          },
          "internal_post": {
            "type": "object",
            "required": ["severity", "commander", "comms_lead", "blast_radius", "current_hypothesis", "actions_in_flight", "incident_link", "next_checkpoint_at"],
            "properties": {
              "severity": {"$ref": "#/definitions/severity"},
              "commander": {"$ref": "#/definitions/person"},
              "comms_lead": {"$ref": "#/definitions/person"},
              "blast_radius": {"$ref": "#/definitions/filled_text"},
              "current_hypothesis": {"type": "string", "minLength": 5, "not": {"pattern": "\\{\\{[a-z_]+\\}\\}"}},
              "actions_in_flight": {"type": "array", "minItems": 1, "items": {"type": "object", "required": ["action", "owner"], "properties": {"action": {"type": "string", "minLength": 5}, "owner": {"$ref": "#/definitions/person"}}}},
              "incident_link": {"type": "string", "pattern": "^https?://\\S+$"},
              "next_checkpoint_at": {"$ref": "#/definitions/datetime_tz"}
            }
          },
          "exec_brief": {
            "type": "object",
            "required": ["customer_impact", "eta", "decisions_needed", "what_is_being_done", "next_update_at", "word_count", "technical_narrative"],
            "additionalProperties": false,
            "properties": {
              "customer_impact": {
                "type": "object",
                "required": ["customers_affected", "revenue_at_risk", "sla_credits_exposed"],
                "properties": {
                  "customers_affected": {"type": "string", "minLength": 2},
                  "revenue_at_risk": {"type": "string", "minLength": 2},
                  "sla_credits_exposed": {"type": "string", "minLength": 2}
                }
              },
              "eta": {"type": "string", "minLength": 5, "pattern": "(?i)(^[0-9]{4}-|unknown, next update at )"},
              "decisions_needed": {"type": "array", "items": {"type": "string", "minLength": 5}},
              "what_is_being_done": {"$ref": "#/definitions/filled_text"},
              "next_update_at": {"$ref": "#/definitions/datetime_tz"},
              "word_count": {"type": "integer", "minimum": 20, "maximum": 150},
              "technical_narrative": {"const": false}
            }
          },
          "resolved": {
            "type": "object",
            "required": ["start_at", "end_at", "affected_scope", "fix_applied", "postmortem_due", "post_incident_email_sent_at"],
            "properties": {
              "start_at": {"$ref": "#/definitions/datetime_tz"},
              "end_at": {"$ref": "#/definitions/datetime_tz"},
              "affected_scope": {"$ref": "#/definitions/filled_text"},
              "fix_applied": {"$ref": "#/definitions/filled_text"},
              "postmortem_due": {"$ref": "#/definitions/date"},
              "post_incident_email_sent_at": {"anyOf": [{"$ref": "#/definitions/datetime_tz"}, {"type": "null"}]}
            }
          }
        }
      }
    }
  }
}

example.code:
{
  "service": "checkout-api",
  "header": {"owner": "pm:olena.k", "version": "1.3.0", "last_reviewed": "2026-05-04"},
  "severity_matrix": [
    {"severity": "P1", "audiences": ["status_page", "customer_email", "exec_brief", "internal_channel"], "first_post_deadline_minutes": 15, "update_interval_minutes": 30, "post_incident_email_deadline_hours": 72},
    {"severity": "P2", "audiences": ["status_page", "exec_brief", "internal_channel"], "first_post_deadline_minutes": 30, "update_interval_minutes": 60, "post_incident_email_deadline_hours": 120},
    {"severity": "P3", "audiences": ["internal_channel"], "first_post_deadline_minutes": 60, "update_interval_minutes": 120, "post_incident_email_deadline_hours": 240}
  ],
  "token_list": ["incident_id", "state", "timestamp", "impact", "next_update_at", "customer_impact", "eta", "decisions_needed", "what_is_being_done", "severity", "commander", "comms_lead", "blast_radius", "hypothesis", "actions", "incident_link", "next_checkpoint_at", "start_at", "end_at", "fix_applied", "postmortem_due"],
  "templates": {
    "status_page": {"body": "{{state}} ({{timestamp}}): {{impact}}. We will post the next update by {{next_update_at}}.", "last_drilled": "2026-04-20"},
    "customer_email": {"body": "Subject: {{incident_id}} service disruption. We are aware of an issue affecting {{impact}}. Our team is working on it; next update by {{next_update_at}}. We will share a full report at {{postmortem_due}}.", "last_drilled": "2026-04-20"},
    "exec_brief": {"body": "Impact: {{customer_impact}}. ETA: {{eta}}. Decisions needed from you: {{decisions_needed}}. In progress: {{what_is_being_done}}. Next update: {{next_update_at}}.", "last_drilled": "2026-04-20"},
    "internal_channel": {"body": "Sev {{severity}} | IC {{commander}} | Comms {{comms_lead}} | Blast radius: {{blast_radius}} | Hypothesis: {{hypothesis}} | In flight: {{actions}} | Channel: {{incident_link}} | Next checkpoint {{next_checkpoint_at}}", "last_drilled": "2026-04-20"}
  },
  "incidents": [
    {
      "incident_id": "INC-2041",
      "severity": "P1",
      "declared_at": "2026-05-12T09:02+02:00",
      "audiences_sent": ["status_page", "customer_email", "exec_brief", "internal_channel"],
      "updates": [
        {"channel": "status_page", "state": "Investigating", "posted_at": "2026-05-12T09:10+02:00", "minutes_after_declaration": 8, "impact": "Checkout for EU customers returns errors; browsing and cart are unaffected", "text": "Investigating (2026-05-12 09:10 CEST): checkout for EU customers returns errors; browsing and cart are unaffected. We will post the next update by 09:40 CEST.", "component_status_matches_text": true, "next_update_at": "2026-05-12T09:40+02:00", "review": {"unconfirmed_cause": false, "blame": false, "internal_names": false, "customer_pii": false}, "approved_by": "dana.r"},
        {"channel": "customer_email", "posted_at": "2026-05-12T09:14+02:00", "minutes_after_declaration": 12, "text": "We are aware of an issue affecting checkout for EU customers since 09:02 CEST. Browsing and cart are unaffected. Our team is working on it; next update by 09:40 CEST.", "next_update_at": "2026-05-12T09:40+02:00", "review": {"unconfirmed_cause": false, "blame": false, "internal_names": false, "customer_pii": false}, "approved_by": "dana.r"},
        {"channel": "status_page", "state": "Identified", "posted_at": "2026-05-12T09:38+02:00", "minutes_after_declaration": 36, "impact": "Checkout for EU customers returns errors; browsing and cart are unaffected", "text": "Identified (2026-05-12 09:38 CEST): the fault is isolated and a fix is being applied; checkout for EU customers still returns errors. Next update by 10:08 CEST.", "component_status_matches_text": true, "next_update_at": "2026-05-12T10:08+02:00", "review": {"unconfirmed_cause": false, "blame": false, "internal_names": false, "customer_pii": false}, "approved_by": "dana.r"},
        {"channel": "status_page", "state": "Monitoring", "posted_at": "2026-05-12T10:05+02:00", "minutes_after_declaration": 63, "impact": "Checkout for EU customers recovering; error rate back to normal since 10:01 CEST", "text": "Monitoring (2026-05-12 10:05 CEST): a fix has been applied and checkout for EU customers is recovering; error rate back to normal since 10:01 CEST. Next update by 10:35 CEST.", "component_status_matches_text": true, "next_update_at": "2026-05-12T10:35+02:00", "review": {"unconfirmed_cause": false, "blame": false, "internal_names": false, "customer_pii": false}, "approved_by": "dana.r"},
        {"channel": "status_page", "state": "Resolved", "posted_at": "2026-05-12T10:33+02:00", "minutes_after_declaration": 91, "impact": "Checkout for EU customers, 09:02 to 10:01 CEST", "text": "Resolved (2026-05-12 10:33 CEST): between 09:02 and 10:01 CEST checkout for EU customers returned errors. A configuration change in our payment routing was rolled back. A post-incident report will be published by 2026-05-15.", "component_status_matches_text": true, "next_update_at": null, "approved_by": "dana.r"}
      ],
      "internal_post": {
        "severity": "P1",
        "commander": "ihor.m",
        "comms_lead": "dana.r",
        "blast_radius": "EU checkout, roughly 38% of daily order volume; US and APAC unaffected",
        "current_hypothesis": "payment-router config push at 08:58 changed the EU PSP endpoint; rollback in progress",
        "actions_in_flight": [{"action": "Roll back payment-router config to 08:40 revision", "owner": "taras.v"}, {"action": "Pull EU error-rate graph into the incident channel", "owner": "maksym.d"}],
        "incident_link": "https://acme.slack.com/archives/C0INC2041",
        "next_checkpoint_at": "2026-05-12T09:30+02:00"
      },
      "exec_brief": {
        "customer_impact": {"customers_affected": "EU customers, about 38% of daily orders", "revenue_at_risk": "about 41k EUR per hour of outage", "sla_credits_exposed": "3 enterprise contracts with 99.9% monthly SLA"},
        "eta": "unknown, next update at 09:40 CEST",
        "decisions_needed": ["Approve proactive credit note to the 3 enterprise accounts if outage exceeds 2 hours"],
        "what_is_being_done": "Rolling back a payment routing change; customer email and status page posted at 09:14 CEST",
        "next_update_at": "2026-05-12T09:40+02:00",
        "word_count": 78,
        "technical_narrative": false
      },
      "resolved": {
        "start_at": "2026-05-12T09:02+02:00",
        "end_at": "2026-05-12T10:01+02:00",
        "affected_scope": "Checkout for EU customers; browsing and cart unaffected; US and APAC unaffected",
        "fix_applied": "Payment-router configuration rolled back to the 08:40 revision",
        "postmortem_due": "2026-05-15",
        "post_incident_email_sent_at": "2026-05-14T16:00+02:00"
      }
    }
  ]
}

{
  "service": "checkout-api",
  "header": {"owner": "pm:olena.k", "version": "1.3.0", "last_reviewed": "2026-05-04"},
  "severity_matrix": [
    {"severity": "P1", "audiences": ["customer_email", "exec_brief", "internal_channel"], "first_post_deadline_minutes": 15, "update_interval_minutes": 30, "post_incident_email_deadline_hours": 72}
  ],
  "token_list": ["incident_id", "state", "timestamp", "impact", "next_update_at"],
  "templates": {
    "status_page": {"body": "{{state}} ({{timestamp}}): {{impact}}. We will post the next update by {{next_update_at}}.", "last_drilled": "2025-11-03"},
    "customer_email": {"body": "We are aware of an issue affecting {{impact}}. We will keep you posted.", "last_drilled": "2025-11-03"},
    "exec_brief": {"body": "Impact: {{customer_impact}}. ETA: {{eta}}. Decisions needed: {{decisions_needed}}. In progress: {{what_is_being_done}}. Next update: {{next_update_at}}.", "last_drilled": "2025-11-03"},
    "internal_channel": {"body": "Sev {{severity}} | IC {{commander}} | Comms {{comms_lead}} | Blast radius: {{blast_radius}} | Hypothesis: {{hypothesis}} | In flight: {{actions}} | Channel: {{incident_link}} | Next checkpoint {{next_checkpoint_at}}", "last_drilled": "2025-11-03"}
  },
  "incidents": [
    {
      "incident_id": "INC-2041",
      "severity": "P1",
      "declared_at": "2026-05-12T09:02+02:00",
      "audiences_sent": ["status_page", "internal_channel"],
      "updates": [
        {"channel": "status_page", "state": "Investigating", "posted_at": "2026-05-12T09:50+02:00", "minutes_after_declaration": 48, "impact": "Checkout errors", "text": "We are investigating an issue affecting {{impact}} customers. We believe the database cluster db-eu-1 is the cause.", "component_status_matches_text": false, "next_update_at": null, "review": {"unconfirmed_cause": true, "blame": false, "internal_names": true, "customer_pii": false}, "approved_by": "on-call"},
        {"channel": "status_page", "state": "Resolved", "posted_at": "2026-05-12T12:40+02:00", "minutes_after_declaration": 218, "impact": "Checkout errors", "text": "The issue has been resolved. Thank you for your patience while we worked on this.", "component_status_matches_text": true, "next_update_at": null, "approved_by": "dana.r"}
      ],
      "internal_post": {
        "severity": "P1",
        "commander": "team",
        "comms_lead": "dana.r",
        "blast_radius": "EU checkout, roughly 38% of daily order volume",
        "current_hypothesis": "payment-router config push changed the EU PSP endpoint",
        "actions_in_flight": [],
        "incident_link": "https://acme.slack.com/archives/C0INC2041",
        "next_checkpoint_at": "2026-05-12T09:30+02:00"
      },
      "exec_brief": {
        "customer_impact": {"customers_affected": "EU customers", "revenue_at_risk": "significant", "sla_credits_exposed": "some"},
        "eta": "soon",
        "decisions_needed": [],
        "what_is_being_done": "At 08:58 a configuration push to the payment router changed the EU PSP endpoint; the connection pool then exhausted because retries doubled; we are rolling back and also considering a hotfix to the pool sizing which needs a restart of the three router pods in eu-west-1",
        "next_update_at": "2026-05-12T09:40+02:00",
        "word_count": 240,
        "technical_narrative": true
      }
    }
  ]
}
